import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function GET() {
    try {
        console.log('Health test: starting Supabase update...');
        const { error } = await supabase
            .from('matches')
            .update({ scoreA: 0 })
            .eq('id', '30d4ca1e-96d7-4a5f-840f-d4defa16615e');

        if (error) {
            console.error('Health test error:', error);
            return NextResponse.json({ status: 'error', error }, { status: 500 });
        }

        return NextResponse.json({ status: 'ok', message: 'Update successful' });
    } catch (err: any) {
        return NextResponse.json({ status: 'error', error: err.message || err }, { status: 500 });
    }
}
